"""Stripe webhook endpoint handling payment_intent.succeeded and payment_intent.payment_failed."""

import os
import logging

import stripe
from flask import Flask, request, jsonify

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")
WEBHOOK_SECRET = os.environ.get("STRIPE_WEBHOOK_SECRET", "")

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("stripe-webhook")

app = Flask(__name__)

_processed_events = set()  # simple idempotency store


@app.route("/webhook", methods=["POST"])
def webhook():
    payload = request.get_data()
    signature = request.headers.get("Stripe-Signature")

    if not WEBHOOK_SECRET:
        return jsonify(error="webhook not configured"), 500

    try:
        event = stripe.Webhook.construct_event(payload, signature, WEBHOOK_SECRET)
    except ValueError:
        return jsonify(error="invalid payload"), 400
    except stripe.error.SignatureVerificationError:
        return jsonify(error="invalid signature"), 400

    event_id = event["id"]
    if event_id in _processed_events:
        return jsonify(status="ignored"), 200

    try:
        if event["type"] == "payment_intent.succeeded":
            _handle_payment_succeeded(event["data"]["object"])
        elif event["type"] == "payment_intent.payment_failed":
            _handle_payment_failed(event["data"]["object"])
        else:
            logger.info("Unhandled event type %s", event["type"])
    except Exception:
        logger.exception("Handler failed for event %s", event_id)
        return jsonify(error="internal error"), 500

    _processed_events.add(event_id)
    return jsonify(status="processed"), 200

