class EventStore:
    """Redis-backed store when REDIS_URL is set, otherwise in-memory.

    The event is only marked processed *after* its handler succeeds, so a
    handler failure returns 500 and Stripe retries the delivery later.
    """

    def __init__(self):
        self._memory = set()
        self._redis = None
        if REDIS_URL:
            import redis
            self._redis = redis.Redis.from_url(REDIS_URL)

    def is_processed(self, event_id):
        if self._redis is not None:
            return bool(self._redis.get(f"stripe:webhook:{event_id}"))
        return event_id in self._memory

    def mark_processed(self, event_id):
        if self._redis is not None:
            self._redis.set(f"stripe:webhook:{event_id}", "1", ex=86_400)
        else:
            self._memory.add(event_id)
